using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NewWeaponAssetBuilder {
 public static void Run(){try{string root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);string dir="Assets/CombatPrototype/Resources/NewWeapons";Directory.CreateDirectory(dir+"/Models");Directory.CreateDirectory(dir+"/Materials");Directory.CreateDirectory(dir+"/Icons");AssetDatabase.Refresh();
 var metal=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.4f,.74f,.75f),name="Twin forged metal"};AssetDatabase.CreateAsset(metal,dir+"/Materials/twin_metal.mat");var leather=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.23f,.12f,.07f),name="Twin grip leather"};AssetDatabase.CreateAsset(leather,dir+"/Materials/twin_grip.mat");
 var go=new GameObject("原创双刃短刀");Part(go,"锻刃",new Vector3(0,.58f,0),new Vector3(.15f,.85f,.065f),metal);Part(go,"护手",new Vector3(0,.13f,0),new Vector3(.35f,.06f,.10f),metal);Part(go,"握柄",new Vector3(0,-.03f,0),new Vector3(.085f,.26f,.085f),leather);PrefabUtility.SaveAsPrefabAsset(go,dir+"/Models/twin_blades.prefab");UnityEngine.Object.DestroyImmediate(go);
 var definition=ScriptableObject.CreateInstance<ItemDefinition>();definition.definitionId="weapon_twin_blades";definition.displayName="双刃";definition.iconKey="twin_blades";definition.category=ItemCategory.Equipment;definition.type=GearType.TwinBlades;definition.width=2;definition.height=3;definition.attackFactor=1;definition.canRotate=true;definition.description="右刃/左刃/交叉；影袭连舞与真实闪避触发反击";AssetDatabase.CreateAsset(definition,"Assets/CombatPrototype/Resources/ItemData/weapon_twin_blades.asset");
 foreach(string key in new[]{"twin_blades","skill_twinblades"}){var texture=new Texture2D(128,128,TextureFormat.RGBA32,false);var pixels=new Color[128*128];for(int y=0;y<128;y++)for(int x=0;x<128;x++){bool blade=(Mathf.Abs(x-(32+(y-30)*.3f))<6||Mathf.Abs(x-(96-(y-30)*.3f))<6)&&y>25&&y<112;bool handle=y>=10&&y<=28&&(x>25&&x<39||x>89&&x<103);pixels[y*128+x]=blade?new Color(.5f,.9f,1):handle?new Color(.55f,.31f,.13f):Color.clear;}texture.SetPixels(pixels);texture.Apply();File.WriteAllBytes("Assets/CombatPrototype/Resources/CatWorld/Icons/"+key+".png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);}
 AssetDatabase.SaveAssets();AssetDatabase.Refresh();foreach(string key in new[]{"twin_blades","skill_twinblades"}){var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/CombatPrototype/Resources/CatWorld/Icons/"+key+".png");importer.textureType=TextureImporterType.Sprite;importer.alphaIsTransparency=true;importer.mipmapEnabled=false;importer.SaveAndReimport();}
 EditorSceneManager.OpenScene(GameEntry.ForestPath);var s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();var model=s.hero.GetComponent<FantasyActorVisual>().model;File.WriteAllText(root+"/bindings.json",JsonUtility.ToJson(new Bones{names=model.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("hand")).Select(t=>t.name).ToArray()},true));EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void RunB2(){try{string root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);string dir="Assets/CombatPrototype/Resources/NewWeapons";var metal=AssetDatabase.LoadAssetAtPath<Material>(dir+"/Materials/twin_metal.mat");var grip=AssetDatabase.LoadAssetAtPath<Material>(dir+"/Materials/twin_grip.mat");var g=new GameObject("原创双手巨剑");Part(g,"厚重剑刃",new Vector3(0,.85f,0),new Vector3(.36f,1.6f,.13f),metal);Part(g,"双手长柄",new Vector3(0,-.25f,0),new Vector3(.13f,.6f,.13f),grip);Part(g,"横护手",Vector3.zero,new Vector3(.65f,.12f,.18f),metal);PrefabUtility.SaveAsPrefabAsset(g,dir+"/Models/greatsword.prefab");UnityEngine.Object.DestroyImmediate(g);var def=ScriptableObject.CreateInstance<ItemDefinition>();def.definitionId="weapon_greatsword";def.displayName="巨剑";def.iconKey="greatsword";def.category=ItemCategory.Equipment;def.type=GearType.Greatsword;def.width=2;def.height=4;def.attackFactor=1;def.canRotate=true;def.description="蓄势扇形重斩 / 破防下劈 / 障碍阻挡地波";AssetDatabase.CreateAsset(def,"Assets/CombatPrototype/Resources/ItemData/weapon_greatsword.asset");MakeIcon("greatsword",0);MakeIcon("skill_greatsword",0);AssetDatabase.SaveAssets();File.WriteAllText(root+"/assets.json","{\"status\":\"PASS\",\"weapon\":\"Greatsword\"}");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void MakeIcon(string key,int variant){var t=new Texture2D(128,128,TextureFormat.RGBA32,false);var pixels=new Color[128*128];for(int y=0;y<128;y++)for(int x=0;x<128;x++){bool blade=variant==0?x>49&&x<79&&y>42&&y<119:y>83&&y<108&&x>23&&x<111;bool handle=x>59&&x<69&&y>10&&y<87;pixels[y*128+x]=blade?new Color(.65f,.85f,.9f):handle?new Color(.55f,.3f,.15f):Color.clear;}t.SetPixels(pixels);t.Apply();string path="Assets/CombatPrototype/Resources/CatWorld/Icons/"+key+".png";File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.Refresh();var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.mipmapEnabled=false;importer.alphaIsTransparency=true;importer.SaveAndReimport();}
 [Serializable]class Bones{public string[] names;}
 static void Part(GameObject root,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.layer=2;g.transform.SetParent(root.transform,false);g.transform.localPosition=pos;g.transform.localScale=size;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=mat;}
}
